// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // newOwner can be any address, including zero, which is the key case
        vm.startPrank(address(this));
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        vm.stopPrank();
        // If the call succeeded, the owner must not be the zero address.
        // The reference always reverts when newOwner is zero, so success is false.
        // The buggy version allows it, making success true and owner equal to zero.
        assertTrue(!success || c.owner() != address(0));
    }
}

