// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // The owner is initially address(this).
        // Renounce ownership to make owner() == address(0) and let the reference succeed on a later transferOwnership.
        // The mutant's onlyOwner also requires owner() == address(0) but then blocks execution (the modifier body never calls _), so it reverts.
        c.renounceOwnership();
        require(c.owner() == address(0), "setup failed");
        // Now call transferOwnership as the original owner (address(this)).
        // Under reference, the onlyOwner modifier passes because msg.sender == address(this) and owner() == address(this) before renounce? No.
        // Wait – after renounceOwnership, owner() == address(0). The reference onlyOwner checks owner() == msg.sender.
        // If msg.sender == address(this) and owner() == address(0), the reference reverts as well because msg.sender != owner().
        // That means the reference would also revert, and we wouldn't observe the bug.
        // We need the reference to succeed. The reference succeeds when current owner calls transferOwnership.
        // After renounce, nobody owns it, so transferOwnership cannot succeed under reference either.
        // Instead, we can prank as the current owner BEFORE renounce.
        // Let's reset: deploy c with owner = address(this). Prank as address(this) to call transferOwnership.
        // Reference: onlyOwner passes because msg.sender == address(this) == owner().
        // Mutant: onlyOwner requires owner() == address(0), which is false, so it reverts.
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

