pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        address currentOwner = c.owner();
        vm.prank(currentOwner);
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }

        if (success) {
            assertEq(c.owner(), newOwner, "owner should be updated on success");
        } else {
            assertEq(c.owner(), currentOwner, "failed call must not change owner");
        }
    }
}

