pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Exclude zero address to avoid the constructor's owner being zero (impossible).
        vm.assume(newOwner != address(0));
        // The contract starts with owner == address(this).
        // Current owner renounces; this should succeed in reference, revert in mutant.
        vm.prank(address(this));
        bool ok;
        try c.renounceOwnership() { ok = true; } catch { ok = false; }
        // After the call, if it succeeded, owner() must be address(0).
        // The reference succeeds (ok == true) and owner becomes zero.
        // The mutant's onlyOwner requires owner() == address(0), so renounceOwnership reverts (ok == false).
        assertTrue(!ok || c.owner() == address(0));
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address newDistributor, address rewardToken, uint256 amount) public {
        require(newDistributor != address(0));
        require(amount > 0);

        c.addReward(rewardToken);
        c.setRewardDistributor(newDistributor);

        bool success = true;
        try c.notifyRewardAmount(rewardToken, amount) {
            success = true;
        } catch {
            success = false;
        }

        assert(success == (newDistributor == address(c.rewardDistributor())));
    }
}

